lemma ConeDual.toNormalizedCertificate_support {L : Nat} {B eps : Real}
    (sigma : ConeDual L B eps) :
    ∀ᵐ v ∂sigma.toNormalizedCertificate.signedMeasure.variation, v ∈ Set.Icc 0 B

affine_latent_polar_weight.statement:
lemma affine_latent_polar_weight {L : Nat} {B eps : Real}
    (sigma : ConeDual L B eps) (i : Fin (L + 2)) :
    |sigma.weights i| * latentPolar sigma (some i) = sigma.weights i

ConeDual.sum_polynomial_eq_zero.statement:
lemma ConeDual.sum_polynomial_eq_zero {L : Nat} {B eps : Real}
    (sigma : ConeDual L B eps) (p : Polynomial Real) (hp : p.natDegree ≤ L) :
    (∑ i, sigma.weights i * p.eval (sigma.nodes i)) = 0

